#!/bin/bash
# Build finance-app.apk without Gradle (aapt2 + javac + d8 + zipalign + apksigner).
# Used by GitHub Actions; also works on a local machine with JDK 17 + Android SDK 34.
set -e
BT="$ANDROID_HOME/build-tools/34.0.0"
PLATFORM="$ANDROID_HOME/platforms/android-34"
mkdir -p build/gen build/classes build/dex
"$BT/aapt2" compile --dir res -o build/compiled.zip
"$BT/aapt2" link -o build/app-unsigned.apk \
  -I "$PLATFORM/android.jar" \
  --manifest AndroidManifest.xml \
  --java build/gen \
  build/compiled.zip \
  --auto-add-overlay
# R.java is generated by aapt2 link into build/gen; locate it
find build -name R.java | head -5
javac -encoding UTF-8 --release 8 -d build/classes \
  -cp "$PLATFORM/android.jar" \
  -sourcepath build/gen:src \
  src/com/muse/finance/MainActivity.java build/gen/com/muse/finance/R.java
jar --create --file build/classes.jar -C build/classes .
"$BT/d8" --min-api 21 --output build/dex build/classes.jar
mkdir -p build/apk
python3 - <<'PY'
import zipfile, shutil
shutil.copyfile("build/app-unsigned.apk", "build/apk/app.apk")
with zipfile.ZipFile("build/apk/app.apk", "a", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as z:
    z.write("build/dex/classes.dex", "classes.dex")
    z.write("assets/www/index.html", "assets/www/index.html")
PY
"$BT/zipalign" -f 4 build/apk/app.apk build/app-aligned.apk
if [ ! -f debug.keystore ]; then
  keytool -genkeypair -v -keystore debug.keystore -alias androiddebugkey \
    -keyalg RSA -keysize 2048 -validity 10000 \
    -storepass android -keypass android \
    -dname "CN=Android Debug,O=Android,C=US"
fi
"$BT/apksigner" sign --ks debug.keystore --ks-key-alias androiddebugkey \
  --ks-pass pass:android --key-pass pass:android \
  --v1-signing-enabled true --v2-signing-enabled true --v3-signing-enabled true \
  --out finance-app.apk build/app-aligned.apk
"$BT/apksigner" verify -v finance-app.apk
ls -lh finance-app.apk
